using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;
class TerreLauncher {
 static string Q(string s){return "\""+System.Text.RegularExpressions.Regex.Replace(System.Text.RegularExpressions.Regex.Replace(s,@"(\\*)""","$1$1\\\""),@"(\\+)$","$1$1")+"\"";}
 [STAThread]static int Main(string[] args){try{string dir=AppDomain.CurrentDomain.BaseDirectory;var c=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(dir,"video-export-wrapper.json")));string addon=Path.Combine(dir,c["addon"]),native=Path.Combine(addon,c["native"]),backend=Path.Combine(dir,c["backend"]);if(!File.Exists(native))throw new FileNotFoundException("视频导出组件缺失，请重新安装组件",native);var values=new[]{"lifecycle","--config",c["config"],"--backend",backend,"--wrapper-pid",Process.GetCurrentProcess().Id.ToString(),"--"}.Concat(args);using(var process=Process.Start(new ProcessStartInfo(native,string.Join(" ",values.Select(Q))){WorkingDirectory=dir,UseShellExecute=false,CreateNoWindow=true})){process.WaitForExit();return process.ExitCode;}}catch(Exception e){MessageBox.Show(e.Message,"Terre 启动失败");return 1;}}
}
